import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./user.css";

export function AnimatedUserIcon(props: AnimatedIconProps) {
  return (
    <AnimatedIconFrame name="user" {...props}>
      <path
        data-part="body"
        d="M20 21a7.53 7.53 0 0 0-7.005-6.934L12 14q-.531.015-1 .038c-3.7.181-6.716 3.268-7 6.962"
      />
      <circle data-part="head" cx="12" cy="7" r="4" />
    </AnimatedIconFrame>
  );
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="user"] {
    & [data-part="head"] {
      --icon-swing: -12deg;
      transform-origin: 12px 21px;
      animation-name: icon-swing;
      animation-duration: var(--icon-duration-long);
    }

    & [data-part="body"] {
      --icon-swing: -5deg;
      --icon-delay: 70ms;
      transform-origin: 12px 21px;
      animation-name: icon-swing;
      animation-duration: var(--icon-duration-long);
    }
  }
}
